import{_ as n,o as r,c as s,a3 as l}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/berufskolleg/gruppenprozesse-bk-mdl-pruefungen.png",c=JSON.parse('{"title":"Mündliche Prüfungen am Berufskolleg festlegen","description":"","frontmatter":{"title":"Mündliche Prüfungen am Berufskolleg festlegen","source_pageid":1288,"source_revision":4714},"headers":[],"relativePath":"zeugnisse/berufskolleg/mdl-pruefungen-festlegen-gruppenprozesse-bk-abschluss.md","filePath":"zeugnisse/berufskolleg/mdl-pruefungen-festlegen-gruppenprozesse-bk-abschluss.md"}'),g={name:"zeugnisse/berufskolleg/mdl-pruefungen-festlegen-gruppenprozesse-bk-abschluss.md"};function t(i,e,p,f,a,o){return r(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="mundliche-prufungen-am-berufskolleg-festlegen" tabindex="-1">Mündliche Prüfungen am Berufskolleg festlegen <a class="header-anchor" href="#mundliche-prufungen-am-berufskolleg-festlegen" aria-label="Permalink to &quot;Mündliche Prüfungen am Berufskolleg festlegen&quot;">​</a></h1><p>Prüfen Sie nach vollständiger Erfassung der Leistungs- und Prüfungsdaten auf notwendige mündliche Prüfungen. Freiwillige Prüfungen werden zusätzlich manuell eingetragen.</p><p><a href="/bilder/berufskolleg/gruppenprozesse-bk-mdl-pruefungen.png"><img src="'+u+'" alt="Über den Gruppeprozess Mündliche Prüfungen festlegen werden Bestehensprüfungen gesetzt." loading="lazy"></a></p><p><em>Über den Gruppeprozess <strong>Mündliche Prüfungen festlegen</strong> werden Bestehensprüfungen gesetzt.</em></p><p>Wurden alle Leistungsdaten und Prüfungsleistungen im Reiter <em>Schüler ➜ BK-Abschluss</em> aufgenommen, kann für eine Gruppe auf Bestehensprüfungen über den Gruppenprozess <strong>Mündliche Prüfungen festlegen</strong> geprüft werden.</p><p>Sinnvolle Ergebnisse werden nur bei einer passenden Auswahl der Schülergruppe erzeugt. Bei Bedarf wird der Haken bei <strong>Mdl. Prüfung</strong> in <em>Schüler ➜ BK-Abschluss</em> gesetzt.</p><p>Die <em>Freiwilligen mündlichen Prüfungen</em>, sofern sie nach der Prüfungsordnung vorgesehen sind, werden zusätzlich manuell im Reiter <em>BK-Abschluss</em> gesetzt.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Mdl._Pr%C3%BCfungen_festlegen_(Gruppenprozesse_BK-Abschluss)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4714.</p>',9)])])}const m=n(g,[["render",t]]);export{c as __pageData,m as default};
